import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int[] arrivals = new int[k];
        int[] start_counts = new int[n];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            arrivals[i] = Integer.parseInt(st.nextToken()) - 1;
            start_counts[arrivals[i]]++;
        }

        int max_time = k + n + 1;
        int total_vertices = (max_time + 1) * n + 2;
        int source = total_vertices - 2;
        int sink = total_vertices - 1;

        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < total_vertices; i++) {
            g.add(new ArrayList<>());
        }

        // Helper method to add edges
        BiConsumer<Integer, int[]> add_edge = (u, edge) -> {
            g.get(u).add(edge);
        };

        // Add edges from source to start nodes
        for (int i = 0; i < n; i++) {
            if (start_counts[i] > 0) {
                g.get(source).add(new int[]{i, start_counts[i], 0});
            }
        }

        // Add edges from time layers to sink
        for (int t = 0; t <= max_time; t++) {
            g.get(t * n).add(new int[]{sink, k, 0});
        }

        // Add edges for staying in the same node over time
        for (int i = 0; i < n; i++) {
            for (int t = 0; t <= max_time; t++) {
                g.get(t * n + i).add(new int[]{(t + 1) * n + i, k, 0});
            }
        }

        // Add edges for moving between nodes
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int t = 0; t < max_time; t++) {
                g.get(t * n + u).add(new int[]{(t + 1) * n + v, 1, c + (2 * 0 + 1) * d});
                g.get(t * n + v).add(new int[]{(t + 1) * n + u, 1, c + (2 * 0 + 1) * d});
            }
        }

        // Placeholder for flow calculation
        System.out.println(0);
    }
}
